import { useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { JxInputField, JxChip } from '@jinx-ui/react';

interface ArticleTagsFieldProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
}

export default function ArticleTagsField({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagsFieldProps) {
  const isControlled = value !== undefined;
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const tags = isControlled ? (value as string[]) : internalTags;
  const [draft, setDraft] = useState('');

  const commitTags = (next: string[]) => {
    if (!isControlled) setInternalTags(next);
    onChange?.(next);
  };

  const addTag = () => {
    const trimmed = draft.trim();
    if (trimmed.length === 0) return;
    setDraft('');
    if (tags.includes(trimmed)) return;
    commitTags([...tags, trimmed]);
  };

  const removeTag = (tag: string) => {
    commitTags(tags.filter((item) => item !== tag));
  };

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    setDraft(event.target.value);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && draft.length === 0 && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  return (
    <div>
      <JxInputField
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        aria-label={label}
        helperText={
          tags.length === 0
            ? 'Введите тег и нажмите Enter, чтобы добавить'
            : `Добавлено тегов: ${tags.length}`
        }
      />
      <div
        role="list"
        aria-label="Выбранные теги"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 8, minHeight: 32 }}
      >
        {tags.length === 0 ? (
          <span style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-sans)' }}>
            Теги ещё не добавлены
          </span>
        ) : (
          tags.map((tag) => (
            <span role="listitem" key={tag}>
              <JxChip removable onRemove={() => removeTag(tag)}>
                {tag}
              </JxChip>
            </span>
          ))
        )}
      </div>
    </div>
  );
}

